const zonas = $input.all().map(i => i.json).sort((a, b) => Number(a.distancia_min_km) - Number(b.distancia_min_km));
const contexto = $('Rota Intenção2').item.json;

let resposta;
if (zonas.length === 0) {
  resposta = '🚚 Consigo confirmar a taxa de entrega assim que você me passar seu endereço! 😊';
} else {
  const linhas = zonas.map(z => {
    const min = Number(z.distancia_min_km);
    const max = Number(z.distancia_max_km);
    const valor = Number(z.valor).toFixed(2).replace('.', ',');
    return `📍 ${min}km a ${max}km: R$ ${valor}`;
  });
  const menorMinimo = Math.min(...zonas.map(z => Number(z.valor_minimo_frete_gratis || Infinity)));
  const freteGratis = isFinite(menorMinimo)
    ? `\n\n🎁 Frete grátis a partir de R$ ${menorMinimo.toFixed(2).replace('.', ',')} em pedidos na faixa mais próxima.`
    : '';
  resposta = `🚚 *Taxa de entrega por distância:*\n\n${linhas.join('\n')}${freteGratis}\n\nMe manda seu bairro que eu confirmo certinho pra você! 😊`;
}

return [{ json: { ...contexto, resposta } }];

const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { ...$('Parse Intenção2').item.json, resposta: 'Não encontrei esse produto no momento. 😔 Quer que eu verifique produtos similares ou fale com um atendente?' } }];
}

const produto = items[0].json;
const intencao = $('Parse Intenção2').item.json.intencao;

let resposta = '';

if (intencao === 'preco') {
  resposta = `✅ *${produto.nome}*\n💰 Preço: R$ ${Number(produto.preco).toFixed(2).replace('.', ',')}\n\nVou confirmar a disponibilidade certinha antes de fechar seu pedido. Deseja adicionar? 🛒`;
} else {
  resposta = `✅ Sim, temos *${produto.nome}*!\n💰 R$ ${Number(produto.preco).toFixed(2).replace('.', ',')}\n\nVou confirmar a disponibilidade certinha antes de fechar seu pedido. Deseja pedir? 😊`;
}

return [{ json: { ...$('Parse Intenção2').item.json, resposta } }];

const resposta = $json.output ?? "{}";

let data = {};

try {
  // Remove possíveis markdown fences do modelo
  const clean = resposta.replace(/```json|```/g, '').trim();
  data = JSON.parse(clean);
} catch(e) {
  console.log('Erro ao parsear JSON:', resposta);
  // Fallback: trata como intenção 'outro' com a resposta bruta
  data = {
    intencao: 'outro',
    entidade: '',
    resposta: resposta
  };
}

return [{
  json: {
    ...$input.item.json,
    intencao: data.intencao || 'outro',
    entidade: data.entidade || '',
    resposta: data.resposta || ''
  }
}];

const resposta = $json.output ?? "{}";

let data = {};

try {
  data = JSON.parse(resposta);
} catch(e) {
  console.log("Erro ao parsear JSON:", resposta);
}

return [{
  json:{
    ...$input.item.json,
    intencao: data.intencao || "",
    entidade: data.entidade || "",
    resposta: data.resposta || ""
  }
}];

const resposta = $json.output || $json.response || "";

let intencao = "outro";
let entidade = null;

try {
  const parsed = JSON.parse(resposta);
  intencao = parsed.intencao;
  entidade = parsed.entidade;
} catch (e) {}

return [{
  json: {
    ...$input.item.json,
    intencao,
    entidade
  }
}];

